<?php require_once 'includes/db.php';require_once 'includes/functions.php';
$q=trim($_GET['q']??'');$cat=trim($_GET['category']??'');
$sql="SELECT * FROM products WHERE active=1";$params=[];$types='';
if($q!==''){$sql.=" AND (name LIKE ? OR description LIKE ?)";$like="%$q%";$params=[$like,$like];$types='ss';}
if($cat!==''){$sql.=" AND category=?";$params[]=$cat;$types.='s';}$sql.=" ORDER BY id DESC";
$s=$conn->prepare($sql);if($params)$s->bind_param($types,...$params);$s->execute();$products=$s->get_result()->fetch_all(MYSQLI_ASSOC);
$cats=$conn->query("SELECT DISTINCT category FROM products WHERE active=1 ORDER BY category")->fetch_all(MYSQLI_ASSOC);$title='Shop';include 'includes/header.php';?>
<section class="hero"><div><small>THE LITTLE THINGS, DONE WELL</small><h1>Find your next<br><em>favorite thing.</em></h1><p>Everyday essentials and thoughtful finds, all in one place.</p><a class="btn dark" href="#products">Explore collection →</a></div><div class="hero-art"><div class="sun"></div><div class="bag"><b>GOOD<br>FINDS</b></div><span>CURATED FOR YOU</span></div></section>
<section id="products"><div class="heading"><div><small>THE COLLECTION</small><h2>Shop all products</h2></div><span class="muted"><?=count($products)?> items</span></div>
<form class="filters"><input name="q" value="<?=e($q)?>" placeholder="Search products..."><select name="category"><option value="">All categories</option><?php foreach($cats as $c):?><option <?= $cat===$c['category']?'selected':''?>><?=e($c['category'])?></option><?php endforeach;?></select><button class="btn">Search</button><?php if($q||$cat):?><a href="index.php">Clear</a><?php endif;?></form>
<div class="grid"><?php if(!$products):?><div class="empty"><h3>No products found</h3><p>Try a different search.</p></div><?php endif;?><?php foreach($products as $p):?><article class="card"><a href="product.php?id=<?=$p['id']?>" class="pic"><img src="<?=e($p['image_url'])?>" alt="<?=e($p['name'])?>" onerror="this.src='assets/product.svg'"><span><?=e($p['category'])?></span></a><div class="cardbody"><a class="pname" href="product.php?id=<?=$p['id']?>"><?=e($p['name'])?></a><p><?=e(mb_strimwidth($p['description'],0,75,'…'))?></p><div class="price-row"><b>₹<?=number_format($p['price'],2)?></b><form method="post" action="cart.php"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="add"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="add" <?=!$p['stock']?'disabled':''?>><?=!$p['stock']?'Sold out':'＋ Add'?></button></form></div></div></article><?php endforeach;?></div></section>
<?php include 'includes/footer.php';?>